import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0049: Native map input ownership","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0049-native-map-input-ownership.md","filePath":"adrs/0049-native-map-input-ownership.md","lastUpdated":1789092097000}`),u={name:`adrs/0049-native-map-input-ownership.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[5]||=a(`<h1 id="adr-0049-native-map-input-ownership" tabindex="-1">ADR-0049: Native map input ownership <a class="header-anchor" href="#adr-0049-native-map-input-ownership" aria-label="Permalink to “ADR-0049: Native map input ownership”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-06 · Refines <a href="/adrs/0047-native-graph-controls-and-session-charts">ADR-0047</a> and <a href="/adrs/0048-spatial-memory-and-knowledge-graph">ADR-0048</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Click-to-activate combined SwiftUI tap gestures and keyboard focus with a separate native event monitor. Blank viewport hit testing and focus transitions could prevent activation or clear it immediately. Custom Records/Map buttons also lacked an explicit full-segment hit area, making clicks beside their text unreliable.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>One native NSView responder owns the graph&#39;s pointer, trackpad, and keyboard input. Clicking activates it and makes it first responder. Pointer exit, first-responder resignation, scene deactivation, or view removal releases it. Inactive scroll events pass up the responder chain; active scroll, drag, pinch, and right-drag update the existing camera. There are no app-wide event monitors and no competing SwiftUI focus or gesture state.</p><p>Pointer selection and hovering use the same projected coordinates as rendering and choose the nearest-depth node when targets overlap. Native input receives drags even when they start on a node. SwiftUI node buttons remain accessibility actions without competing for pointer events. The active-state badge remains; bottom gesture instructions are removed. The type legend and graph counts remain visible.</p><p>Each Records/Map/Connections button declares a rectangular hit area inside its full-width label, with a 28-point minimum height. Selection remains local and does not trigger network loading.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2>`,9),c(`ul`,null,[l[3]||=c(`li`,null,`Input ownership has one lifecycle and the inactive graph cannot consume page scrolling.`,-1),l[4]||=c(`li`,null,`Tests exercise actual native responder methods for click activation, scroll forwarding, exit, resignation, selection, and reactivation. Live UI checks remain necessary for host hit testing.`,-1),c(`li`,null,[l[1]||=i(`The same behavior applies to `,-1),r(m,{term:`pen`},{default:n(()=>[...l[0]||=[i(`Pen`,-1)]]),_:1}),l[2]||=i(`, Settings, and expanded graphs without new dependencies.`,-1)])]),l[6]||=c(`h2`,{id:`alternatives-considered`,tabindex:`-1`},[i(`Alternatives considered `),c(`a`,{class:`header-anchor`,href:`#alternatives-considered`,"aria-label":`Permalink to “Alternatives considered”`},`​`)],-1),l[7]||=c(`p`,null,`More flags or delayed retries around SwiftUI focus would preserve competing state owners. An always-active wheel monitor would restore interaction by breaking page scrolling again.`,-1)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};